import java.io.*;
import java.util.*;

public class PuzzleMain {
    public static void main(String[] args) throws IOException {
        new PalindromeGame();
    }
}

class PalindromeGame {
    PalindromeGame() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());
        String s = br.readLine();
        char[] word = s.toCharArray();
        int[] values = new int[n];
        String[] valsStr = br.readLine().split(" ");
        for (int i = 0; i < n; i++) {
            values[i] = Integer.parseInt(valsStr[i]);
        }
        int[] freq = new int[26];
        int pairCount = 0;
        for (int i = 0; i < n / 2; i++) {
            if (word[i] == word[n - i - 1]) {
                freq[word[i] - 'a']++;
                pairCount++;
            }
        }
        int maxFreq = 0;
        boolean dominantCharFlag = false;
        int dominantCharIdx = -1;
        for (int i = 0; i < 26; i++) {
            if (freq[i] * 2 > pairCount) {
                dominantCharFlag = true;
                dominantCharIdx = i;
            }
        }
        if (!dominantCharFlag) {
            long totalCostSum = 0;
            for (int i = 0; i < n / 2; i++) {
                if (word[i] != word[n - i - 1]) {
                    totalCostSum += values[i] + values[n - i - 1];
                } else {
                    totalCostSum += Math.max(values[i], values[n - i - 1]);
                }
            }
            pw.println(totalCostSum);
        } else {
            int excessCount = freq[dominantCharIdx] - (pairCount - freq[dominantCharIdx]);
            ArrayList<Integer> minValList = new ArrayList<>();
            for (int i = 0; i < n / 2; i++) {
                if (word[i] != word[n - i - 1] && word[i] != ('a' + dominantCharIdx) && word[n - i - 1] != ('a' + dominantCharIdx)) {
                    minValList.add(Math.min(values[i], values[n - i - 1]));
                }
            }
            Collections.sort(minValList);
            long totalSum = 0;
            for (int i = 0; i < n / 2; i++) {
                if (word[i] == word[n - i - 1]) {
                    totalSum += Math.max(values[i], values[n - i - 1]);
                } else {
                    totalSum += values[i] + values[n - i - 1];
                }
            }
            for (int i = 0; i < excessCount && i < minValList.size(); i++) {
                totalSum -= minValList.get(i);
            }
            pw.println(totalSum);
        }
        pw.close();
    }
}
